import { createHash } from 'node:crypto';

// How generated content is marked (PLAN.md §6.4–6.5). Two shapes:
//
// Whole file (per-rule files, `mode: "file"`): a header comment at the top, or right after the
// frontmatter, which has to come first.
//
//   <!-- Generated by ctx-lint from .context/rules. Do not edit: … ctx-lint:hash=0123456789ab -->
//
// Managed block (`mode: "managed-block"`): only the content between the markers is ctx-lint's;
// anything outside them is the user's.
//
//   <!-- ctx-lint:begin hash=0123456789ab -->
//   <!-- Generated from .context/rules. Do not edit inside this block: … -->
//   …
//   <!-- ctx-lint:end -->
//
// The hash covers the generated body only. It has no timestamp, so output is deterministic,
// and `check` can tell when someone edited generated text by hand.

const HEADER = /<!-- Generated by ctx-lint\b[^\n]*?ctx-lint:hash=([0-9a-f]{12}) -->[ \t]*\r?\n?/;
// The hash is optional so a hand-written `<!-- ctx-lint:begin -->` … `<!-- ctx-lint:end -->` pair
// marks where generated content should go.
const BEGIN =
  /<!-- ctx-lint:begin(?: hash=([0-9a-f]{12}))? -->[ \t]*\r?\n(?:<!-- Generated from [^\n]*-->[ \t]*\r?\n)?/;
const END = /\r?\n?<!-- ctx-lint:end -->/;

/** Normalized body text: LF line endings, trimmed, one trailing newline. */
export function normalizeBody(body: string): string {
  return `${body.replace(/\r\n/g, '\n').trim()}\n`;
}

export function hashBody(body: string): string {
  return createHash('sha256').update(normalizeBody(body)).digest('hex').slice(0, 12);
}

export function fileHeader(sources: string, body: string): string {
  return `<!-- Generated by ctx-lint from ${sources}. Do not edit: change the source rules and run \`npx ctx-lint sync\`. ctx-lint:hash=${hashBody(body)} -->`;
}

export function managedBlock(sources: string, body: string): string {
  return [
    `<!-- ctx-lint:begin hash=${hashBody(body)} -->`,
    `<!-- Generated from ${sources}. Do not edit inside this block: change the source rules and run \`npx ctx-lint sync\`. -->`,
    '',
    normalizeBody(body).trimEnd(),
    '',
    '<!-- ctx-lint:end -->',
  ].join('\n');
}

/** A whole generated file: optional frontmatter, the header, then the body. */
export function renderWholeFile(sources: string, body: string, frontmatter?: string): string {
  const head = frontmatter
    ? `${frontmatter}${fileHeader(sources, body)}`
    : fileHeader(sources, body);
  return `${head}\n\n${normalizeBody(body)}`;
}

export interface GeneratedRegion {
  kind: 'file' | 'block';
  /** Hash recorded when the content was generated (`null` for hand-added markers). */
  recordedHash: string | null;
  /** Hash of the body as it is now. Differs from `recordedHash` after a hand edit. */
  actualHash: string;
  /** Offsets of the whole generated region (markers included) in the file. */
  start: number;
  end: number;
  /** Offsets of the header or begin marker, for reporting. */
  markerStart: number;
  markerEnd: number;
}

/** Finds ctx-lint-generated content in a file, or `null` when there is none. */
export function findGenerated(content: string): GeneratedRegion | null {
  const header = HEADER.exec(content);
  // A whole-file header must be the first thing, or come right after the frontmatter.
  if (header && isAtTop(content, header.index)) {
    const body = content.slice(header.index + header[0].length);
    return {
      kind: 'file',
      recordedHash: header[1] as string,
      actualHash: hashBody(body),
      start: 0,
      end: content.length,
      markerStart: header.index,
      markerEnd: header.index + header[0].trimEnd().length,
    };
  }

  const begin = BEGIN.exec(content);
  if (!begin) return null;
  const afterBegin = begin.index + begin[0].length;
  const end = END.exec(content.slice(afterBegin));
  if (!end) return null;
  const body = content.slice(afterBegin, afterBegin + end.index);
  return {
    kind: 'block',
    recordedHash: begin[1] ?? null,
    actualHash: hashBody(body),
    start: begin.index,
    end: afterBegin + end.index + end[0].length,
    markerStart: begin.index,
    markerEnd: begin.index + begin[0].indexOf('-->') + 3,
  };
}

function isAtTop(content: string, index: number): boolean {
  const before = content.slice(0, index).replace(/^﻿/, '');
  if (before.trim() === '') return true;
  return /^---\r?\n[\s\S]*?\r?\n---[ \t]*\r?\n$/.test(before);
}

/** Puts a managed block into existing content, replacing an existing block if there is one. */
export function replaceBlock(existing: string, block: string): string {
  const region = findGenerated(existing);
  if (region?.kind === 'block') {
    return existing.slice(0, region.start) + block + existing.slice(region.end);
  }
  const trimmed = existing.trimEnd();
  return trimmed === '' ? `${block}\n` : `${block}\n\n${trimmed}\n`;
}
